import{_ as a,o as r,c as t,a5 as l}from"./chunks/framework.BF53ZjCA.js";const h=JSON.parse('{"title":"产地 / 处理披露","description":"","frontmatter":{"title":"产地 / 处理披露","grading":"origin-disclosure"},"headers":[],"relativePath":"zh/grading/origin-disclosure.md","filePath":"zh/grading/origin-disclosure.md","lastUpdated":1790876393000}'),i={name:"zh/grading/origin-disclosure.md"};function s(n,e,o,d,c,g){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="产地-处理披露" tabindex="-1">产地 / 处理披露 <a class="header-anchor" href="#产地-处理披露" aria-label="Permalink to &quot;产地 / 处理披露&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>处理状态和产地意见属于披露与实验室报告语境，适用要求取决于司法辖区、 规则、报告和交易场景；它们不是同一套分级指标。</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-origin-disclosure-zh"><p class="gem-identification-boundary__eyebrow">GRADING BOUNDARY</p><h2 id="identification-boundary-origin-disclosure-zh">边界与安全</h2><p>本页用于区分处理披露与产地意见，不提供法律意见、价格预测或具体样品的最终披露结论。任何“必须披露”都必须绑定适用司法辖区、规则、报告和交易语境；高价值交易应以合格实验室和专业顾问意见为准。 </p></aside><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>“No Indications of Treatment”表示未观察到处理迹象，不等于绝对证明从未处理；价格也不能仅凭这一项确定。</li><li>一般处理 (常规)：如红/蓝宝石热处理，是否需要披露取决于适用规则、报告和交易语境；不能作全球统一法律结论。</li><li>优化处理 (enhancement)：如祖母绿浸油 / 染色 / 填充，需同时说明稳定性、护理、报告用语和适用披露规则。</li><li>产地意见 (origin opinion)：结合包裹体组合与微量元素等证据，由实验室出具意见，可能无法判定，也不是宝石分级。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>等级</th><th>备注</th></tr></thead><tbody><tr><td>红宝石</td><td>heated (H)</td><td>处理披露示例；不单独推出价格上限</td></tr><tr><td>祖母绿</td><td>minor oil (Cedarwood)</td><td>需结合稳定性、护理、报告用语和适用规则</td></tr><tr><td>蓝宝石</td><td>unheated, Kashmir</td><td>未观察到处理迹象与产地意见是两个独立维度</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页用于理解分级描述和报告术语；来源说明知识依据，不代表仅凭本页即可完成具体样品分级、估值、鉴定或产地判断。</p><ul><li><a href="https://www.gia.edu/diamond-quality-factor" target="_blank" rel="noreferrer">GIA：钻石质量要素</a><span>钻石颜色、净度、切工与克拉重量等质量描述因素；不作为价格公式</span><small>打开来源 ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-clarity/" target="_blank" rel="noreferrer">GIA 4Cs：钻石净度</a><span>FL–I3 净度等级和 10× 观察条件的入门说明</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA：有色宝石价值要素与切工质量</a><span>不同品种的颜色、切工、净度、耐久性与市场因素需要综合理解</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/UK-EN/emerald-quality-factor" target="_blank" rel="noreferrer">GIA：祖母绿质量要素</a><span>祖母绿颜色、透明度、内含物和处理语境的品种化示例</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA：宝石产地分析方法</a><span>产地意见需要包裹体、微量元素等多维证据，并可能无法判定</span><small>打开来源 ↗</small></li><li><a href="https://www.ftc.gov/news-events/topics/tools-consumers/jewelry-guides" target="_blank" rel="noreferrer">FTC：珠宝、贵金属与宝石指南</a><span>美国消费者与营销披露指南；不自动等同于所有地区的法律要求</span><small>打开来源 ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-origin-disclosure-zh"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-origin-disclosure-zh">本页证据映射</h2><p class="gem-reference-block__intro">把本页的教学主张映射到来源，并标注它在知识库中的证据状态。</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">来源支持</strong><span>产地是实验室依据多维证据给出的意见，可能出现无法判定，不是宝石分级。</span><small>GIA：宝石产地分析方法</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">来源支持</strong><span>处理披露要求取决于适用的司法辖区、规则、报告和交易语境，不能概括为全球统一的法律结论。</span><small>FTC：珠宝、贵金属与宝石指南</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">教学归纳</strong><span>处理状态会影响报告解读、稳定性、护理和市场评价，但不能仅凭处理标签推出价格上限。</span><small>GIA：祖母绿质量要素；FTC：珠宝、贵金属与宝石指南</small></li></ul></aside><p><em>详见<a href="./intro.html">分级总览</a>。</em></p>',11)])])}const p=a(i,[["render",s]]);export{h as __pageData,p as default};
